const folders = items.flatMap(item =>
  item.json.files || []
);

const deduped = [];
const seen = new Set();

for (const folder of folders) {
  if (!folder.id || seen.has(folder.id)) {
    continue;
  }

  seen.add(folder.id);
  deduped.push(folder);
}

return [
  {
    json: {
      files: deduped
    }
  }
];

const ROOT_FOLDER_ID = "REPLACE_WITH_YOUR_GOOGLE_DRIVE_ROOT_FOLDER_ID";
const LIVING_KNOWLEDGE_FOLDER_NAME = "Living Knowledge";

const folders = items.flatMap(item => item.json.files || []);
const childrenByParent = new Map();

for (const folder of folders) {
  for (const parentId of folder.parents || []) {
    if (!childrenByParent.has(parentId)) {
      childrenByParent.set(parentId, []);
    }
    childrenByParent.get(parentId).push(folder);
  }
}

const eligibleFolderIds = new Set();
const visited = new Set();
const stack = (childrenByParent.get(ROOT_FOLDER_ID) || []).map(folder => ({ folder, insideLivingKnowledge: false }));

while (stack.length > 0) {
  const current = stack.pop();
  const folder = current.folder;
  if (!folder || visited.has(folder.id)) continue;
  visited.add(folder.id);

  const insideLivingKnowledge = current.insideLivingKnowledge || folder.name === LIVING_KNOWLEDGE_FOLDER_NAME;
  if (insideLivingKnowledge) eligibleFolderIds.add(folder.id);

  for (const child of childrenByParent.get(folder.id) || []) {
    stack.push({ folder: child, insideLivingKnowledge });
  }
}

return [...eligibleFolderIds].map(folderId => ({ json: { folderId } }));

const allFiles = items.flatMap(item =>
  item.json.files || []
);

const deduped = [];
const seen = new Set();

for (const file of allFiles) {
  if (
    typeof file.name === "string" &&
    file.name.toLowerCase().endsWith(".md") &&
    !seen.has(file.id)
  ) {
    seen.add(file.id);
    deduped.push({
      json: {
        id: file.id,
        name: file.name,
        modifiedTime: file.modifiedTime
      }
    });
  }
}

return deduped.slice(0, 10);

const query =
  $('Webhook')
    .first()
    .json.body.query
    .toLowerCase()
    .trim();

// SPLIT QUERY INTO TOKENS
const tokens =
  query
    .split(/\s+/)
    .filter(Boolean);

return items.map(item => {

  const title =
    (item.json.name || "")
      .toLowerCase();

  const content =
    (item.json.data || "")
      .toLowerCase();

  let score = 0;
  let mentionCount = 0;
  let matchedTokens = 0;

  const reasons = [];

  // ======================
  // TITLE MATCH
  // ======================

  let titleMatches = 0;

  for (const token of tokens) {

    if (title.includes(token)) {
      score += 20;
      titleMatches++;
    }
  }

  if (titleMatches > 0) {
    reasons.push(
      `title match (${titleMatches}) +${titleMatches * 20}`
    );
  }

  // ======================
  // CONTENT MATCH
  // ======================

  for (const token of tokens) {

    const matches =
      content.match(
        new RegExp(token, "g")
      ) || [];

    const count =
      matches.length;

    mentionCount += count;

    // TOKEN COVERAGE
    if (count > 0) {
      matchedTokens++;
    }

    // TOKEN SCORE
    score += Math.min(count, 10);
  }

  const mentionScore =
    Math.min(
      mentionCount,
      20
    );

  if (mentionCount > 0) {
    reasons.push(
      `mentions ${mentionCount} (+${mentionScore})`
    );
  }

  // ======================
  // COVERAGE BONUS
  // ======================

  const coverageBonus =
    matchedTokens * 15;

  score += coverageBonus;

  if (matchedTokens > 0) {
    reasons.push(
      `concept coverage (${matchedTokens}) +${coverageBonus}`
    );
  }

  // ======================
  // RECENCY BONUS
  // ======================

  const modified =
    new Date(
      item.json.modifiedTime
    );

  const now =
    new Date();

  const diffDays =
    (now - modified) /
    (1000 * 60 * 60 * 24);

  if (diffDays <= 7) {
    score += 10;

    reasons.push(
      "recent +10"
    );

  } else if (
    diffDays <= 30
  ) {

    score += 5;

    reasons.push(
      "recent +5"
    );
  }

  // ======================
  // CLEAN CONTENT
  // ======================

  const cleanedContent =
    content
      .replace(/_{3,}/g, " ")
      .replace(/[0-9️⃣]+/g, " ")
      .replace(/\*\s+/g, "• ")
      .replace(/\r?\n/g, " ")
      .replace(/\s+/g, " ")
      .trim();

  // ======================
  // SPLIT INTO CHUNKS
  // ======================

  const chunks =
    cleanedContent
      .split(/[.!?]\s+|\n+/)
      .filter(
        chunk =>
          chunk.trim().length > 80
      );

  // ======================
  // BEST MEMORY SNIPPET
  // ======================

  let bestChunk = "";
  let bestChunkScore = -1;

  for (const chunk of chunks) {

    const lowerChunk =
      chunk.toLowerCase();

    let chunkScore = 0;

    let chunkMatchedTokens = 0;

    for (const token of tokens) {

      const matches =
        lowerChunk.match(
          new RegExp(
            token,
            "g"
          )
        ) || [];

      const count =
        matches.length;

      if (count > 0) {
        chunkMatchedTokens++;
      }

      chunkScore +=
        count * 5;

      if (
        lowerChunk.includes(
          token
        )
      ) {
        chunkScore += 2;
      }
    }

    // reward chunks matching more concepts
    chunkScore +=
      chunkMatchedTokens * 10;

    // slight preference for richer chunks
    chunkScore +=
      Math.min(
        chunk.length / 100,
        5
      );

    if (
      chunkScore >
      bestChunkScore
    ) {
      bestChunkScore =
        chunkScore;

      bestChunk =
        chunk.trim();
    }
  }

  // ======================
  // PREVIEW
  // ======================

  const previewLength = 5000;

  const buildPreview = (start, end) => {

    if (
      start > 0 &&
      /[\uDC00-\uDFFF]/.test(
        cleanedContent.charAt(start)
      )
    ) {
      start++;
    }

    if (
      end < cleanedContent.length &&
      /[\uD800-\uDBFF]/.test(
        cleanedContent.charAt(end - 1)
      )
    ) {
      end--;
    }

    return (
      (start > 0 ? "..." : "") +
      cleanedContent.substring(start, end) +
      (end < cleanedContent.length ? "..." : "")
    );
  };

  let preview = "";

  if (bestChunk) {

    const matchIndex =
      cleanedContent.indexOf(
        bestChunk
      );

    if (matchIndex >= 0) {

      const halfWindow =
        Math.floor(
          previewLength / 2
        );

      let start =
        Math.max(
          0,
          matchIndex - halfWindow
        );

      let end =
        Math.min(
          cleanedContent.length,
          start + previewLength
        );

      if (
        end - start < previewLength
      ) {
        start =
          Math.max(
            0,
            end - previewLength
          );
      }

      preview =
        buildPreview(
          start,
          end
        );

    } else {

      const end =
        Math.min(
          previewLength,
          cleanedContent.length
        );

      preview =
        buildPreview(
          0,
          end
        );
    }

  } else {

    const end =
      Math.min(
        previewLength,
        cleanedContent.length
      );

    preview =
      buildPreview(
        0,
        end
      );
  }

  return {
    json: {
      ...item.json,
      query,
      tokens,
      score,
      mentionCount,
      matchedTokens,
      reasons,
      preview
    }
  };
});
